L000150	 \includegraphics[width=\linewidth]{Final_Pulse_Sequence.png}
L000151	 \caption{Experimental pulse sequence for creating entangled photon pairs. The ion is Doppler cooled for $6$ $\mathrm{ \mu s}$ before being optically pumped into the S$_{1/2}$,$m_j=-1/2$ state with >95\% efficiency. From this state the ion is transferred to the D$_{3/2}$,$m_j=-1/2$ state via STIRAP. A bi-chromatic 850 nm pulse produces an ion-photon entangled state. A second bi-chromatic drive at 854 nm generates a second photon producing a two-photon entangled state.
L000152	   \label{fig:seq}}
L000153	   \end{center}
